esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking arbitrary candidate newOwner and a boolean
    // indicating whether we attempt the call as admin or not is unnecessary because
    // the test contract is the deployer of C (admin). We still take an address param.
    function run(address candidate) public payable {
        // read owner before
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;

        bool reverted;
        bool ret;
        // attempt the state-changing call; record whether it reverted and any return
        bool success = c.setOwner(candidate); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
            ret = false;
        } else {
            reverted = false;
            ret = success;
        }

        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // General rule: ownerAfter == candidate if and only if the call did not revert and returned true.
        // This ties observable return/revert to the state change of owner.
        assert( (ownerAfter == candidate) == (!reverted && ret) );
    }

    // receive to allow payable if needed in future
    receive() external payable {}
}

